update public.products set slug='dish-wash', category_id=(select id from public.product_categories where slug='kitchen'), mrp_inr=110, short_description='Concentrated dish wash liquid that cuts grease for a sink full of sparkling utensils.', description='KLEEVO Dish Wash is a powerful cleaning formula for everyday utensils. Just one teaspoon mixed in a bowl of water is enough to clean a sink full of vessels — it lifts oil, grease and food stains and leaves steel, glass and non-stick cookware sparkling clean.', features=array['Removes tough oil & grease','Just 1 teaspoon per bowl','Sparkling utensils','Gentle on hands']::text[], how_to_use=array['Take 1 teaspoon full of dish wash.','Mix it in a bowl of water.','Dip a scrubber and squeeze to get powerful result.','Clean to get a sink full of sparkling utensils.']::text[], caution=array['For external use only.','Keep out of reach of children.','Avoid contact with eye. In case of contact, wash immediately with plenty of water and seek medical advice.','Do not mix with any other household cleaner or any other material in this liquid.','Store away from direct sunlight.']::text[] where sku='KLV-DW-500';
update public.products set slug='cloth-detergent', category_id=(select id from public.product_categories where slug='laundry'), mrp_inr=120, short_description='Fabrics care detergent liquid — best for machine wash and bucket wash.', description='KLEEVO Fabrics Care Detergent Liquid with a new formula and Clean Action technology removes tough stains while caring for your fabrics. Dissolves completely, leaves no residue, and is best used for both washing machines and bucket wash.', features=array['New formula','Best for machine & bucket wash','Removes tough stains','Cares for whites & colours']::text[], how_to_use=array['Always wash whites and colours separately.','Always dissolve the liquid completely in water before adding clothes.','For really tough stains, soak clothes in the solution for 30 minutes before washing.','Always check the fabric washing instructions on the garment.']::text[], caution=array['For external use only.','Avoid contact with eyes. In case of contact, wash immediately with plenty of water and seek medical advice.','Keep out of reach of children.','Store away from direct sunlight.']::text[] where sku='KLV-CD-500';
update public.products set slug='floor-wash', category_id=(select id from public.product_categories where slug='home'), mrp_inr=110, short_description='Powerful cleaning formula for floors, tiles, wash basins and sinks.', description='KLEEVO Floor Cleaner — "We Will Make It Shine". A powerful cleaning formula that removes tough oil, grease and stains, gives shine, neutralises odour and is safe on hands.', features=array['Removes tough oil, grease & stains','Gives shine','Neutralises odour','Safe on hand']::text[], how_to_use=array['Add the recommended quantity of floor cleaner to a bucket of water.','Dip the mop in the solution and squeeze out excess liquid.','Mop the floor, tiles or surface evenly.','For tough stains, apply directly on the stain, wait a few minutes and wipe clean.']::text[], caution=array['For external use only.','Keep out of reach of children.','Avoid contact with eyes & skin. In case of contact, wash immediately with plenty of water and seek medical advice.','Do not mix with any other household cleaner or any other material in this liquid.','Store away from direct sunlight.']::text[] where sku='KLV-FW-500';
update public.products set slug='toilet-cleaner', category_id=(select id from public.product_categories where slug='bathroom'), mrp_inr=100, short_description='Super active thick formula — works in Indian & Western toilets, safe for septic tanks.', description='The super active formula of KLEEVO Toilet Cleaner helps the liquid stay longer on the commode to make your toilet extra ordinary clean and absolutely sparkling. Toilet cleaner works well in both Indian and Western toilets and is safe for septic tanks.', features=array['Super active formula','Stays longer on the commode','Indian & Western toilets','Safe for septic tanks']::text[], how_to_use=array['Step 1: First flush the toilet and then apply Toilet Cleaner under the rim.','Step 2: Wait for 20 minutes. Brush gently.','Step 3: Flush.']::text[], caution=array['Use only for toilet bowls.','For external use only.','Keep out of reach of children.','Avoid contact with eyes & skin. In case of contact, wash immediately with plenty of water and seek medical advice.','Do not mix with any other household cleaner or any other material in this liquid.','Store away from direct sunlight.']::text[] where sku='KLV-TC-500';
update public.products set slug='bathroom-cleaner', category_id=(select id from public.product_categories where slug='bathroom'), mrp_inr=110, short_description='For sinks, bath tubs, tiles and floors — one bottle for the whole bathroom.', description='KLEEVO Bathroom Cleaner is a powerful cleaning formula for the complete bathroom. It removes soap scum, hard-water marks and stains from sinks, bath tubs, tiles and floors and leaves them fresh and shining.', features=array['Sinks cleaning','Bath tub cleaning','Tiles cleaning','Floor cleaning']::text[], how_to_use=array['Apply the cleaner directly on the surface or on a wet sponge / brush.','Leave for a few minutes to act on stains and hard-water marks.','Scrub gently with a brush or sponge.','Rinse thoroughly with water.']::text[], caution=array['For external use only.','Keep out of reach of children.','Avoid contact with eyes & skin. In case of contact, wash immediately with plenty of water and seek medical advice.','Do not mix with any other household cleaner or any other material in this liquid.','Store away from direct sunlight.']::text[] where sku='KLV-BC-500';
update public.products set slug='car-wash', category_id=(select id from public.product_categories where slug='vehicle'), mrp_inr=210, short_description='Liquid car shampoo for a streak-free, glossy finish. Shake well before use.', description='KLEEVO Car Shampoo gives your vehicle complete care. The liquid shampoo loosens dirt and road grime and rinses off cleanly, leaving the paint glossy and streak-free. Shake well before use.', features=array['Complete care for your car','Glossy, streak-free finish','Rinses off cleanly','Shake well before use']::text[], how_to_use=array['Mix in water (liquid car shampoo).','Rinse the vehicle with fresh water from top down.','Agitate the car shampoo with a wash mitt and apply it to the top of the vehicle, then proceed downwards on the remaining parts including the wheel wells (use a separate wash mitt for wheels).','Remove any excess water with a clean microfibre cloth.']::text[], caution=array['Ensure the vehicle is not under direct sunlight while washing.','Mix the car shampoo and water as directed. Too much concentrated car shampoo may lead to unwanted streaking.','Avoid contact with eyes & skin. In case of contact, wash immediately with plenty of water and seek medical advice immediately.','Store away from direct sunlight. Keep away from children.','Wear hand gloves when making products.','Do not mix with any other household cleaner or any other material in this liquid.']::text[] where sku='KLV-CW-500';
update public.products set slug='glass-cleaner', category_id=(select id from public.product_categories where slug='home'), mrp_inr=110, short_description='Streak-free shine for windows, mirrors, display cases and vehicle glass.', description='KLEEVO Glass Cleaner — Streak Free Shine. A powerful cleaning formula that removes tough oil, grease and stains, gives shine, removes odour and is safe on hands.', features=array['Removes tough oil','Grease & stains','Gives shine','Odour remove','Safe on hand']::text[], how_to_use=array['Spray the cleaner evenly on the glass surface from a distance of about 15–20 cm.','Wipe with a clean, dry, lint-free or microfibre cloth / squeegee.','Buff dry for a streak-free shine.']::text[], caution=array['For external use only.','Keep out of reach of children.','Avoid contact with eye. In case of contact, wash immediately with plenty of water and seek medical advice.','Do not mix with any other household cleaner or any other material in this liquid.','Store away from direct sunlight.','Do not use on electronic items.']::text[] where sku='KLV-GC-500';
